function loadDisplayedMode() {
  var displayedPath = currentEditorFile;
  var modePath = typeof displayedPath === 'string' ? displayedPath : '';
  if (modePath.charAt(0) !== '/') modePath = '/' + modePath;
  if (!/^\/sdcard\/Modes\/oFLua\/[^/]+\/main\.lua$/.test(modePath) ||
      modePath.indexOf('/../') !== -1 || modePath.indexOf('/./') !== -1 ||
      loadedEditorContents === null) {
    $('#load-mode-status').text('Open a live mode main.lua under /sdcard/Modes/oFLua first.');
    return;
  }
  var displayedContents = editor.getValue();
  if (displayedContents !== loadedEditorContents && !window.confirm(
      'This main.lua has unsaved edits. Load the saved version anyway? ' +
      'Your edits will remain in the editor. Cancel to save them first.')) return;
  // Use the displayed file captured above, never workingDir or selected table row.
  if (currentEditorFile !== displayedPath || editor.getValue() !== displayedContents) return;
  $('#load-mode-status').text('Requesting mode load...');
  return $.post(appBaseURL + '/mode_set', { mode: modePath })
    .done(function() {
      $('#load-mode-status').text('Load requested for ' + modePath + ' (saved version).');
    })
